css:
:scope {
  --ink: #2c3e50;
  --muted: #7f8c8d;
  --accent: #3498db;
  --warm: #e67e22;
  --line: #ecf0f1;
  --paper: #fdfdfd;
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--paper);
  line-height: 1.6;
}
.chapter-container {
  max-width: 900px;
  margin: 0 auto;
  padding: 2rem 1rem;
}
.chapter-header h1 {
  font-size: 2rem;
  margin-bottom: 0.5rem;
  color: var(--ink);
  border-bottom: 2px solid var(--accent);
  padding-bottom: 0.5rem;
}
.chapter-takeaway {
  font-size: 1.1rem;
  color: var(--muted);
  margin-bottom: 2rem;
}
.content-block {
  margin-bottom: 3rem;
  padding: 1.5rem;
  border-left: 3px solid var(--line);
  background: #fafafa;
}
.content-block h2 {
  font-size: 1.5rem;
  margin-top: 0;
  color: var(--ink);
}
.formula-box {
  font-family: "Times New Roman", serif;
  font-size: 1.2rem;
  padding: 1rem;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 4px;
  margin: 1rem 0;
  text-align: center;
  overflow-x: auto;
}
.interactive-stepper {
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 1rem;
  background: #fff;
}
.stepper-controls {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
  flex-wrap: wrap;
}
.step-btn {
  padding: 0.5rem 1rem;
  border: 1px solid var(--accent);
  background: #fff;
  color: var(--accent);
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.9rem;
  transition: all 0.2s;
}
.step-btn:hover {
  background: var(--accent);
  color: #fff;
}
.step-btn.active {
  background: var(--accent);
  color: #fff;
}
.step-content {
  display: none;
  animation: fadeIn 0.3s ease;
}
.step-content.active {
  display: block;
}
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
.source-ref {
  margin-top: 1rem;
  font-size: 0.85rem;
  color: var(--muted);
}
.source-ref button {
  background: none;
  border: 1px solid var(--muted);
  color: var(--muted);
  padding: 0.2rem 0.5rem;
  border-radius: 3px;
  cursor: pointer;
  font-size: 0.8rem;
  margin-right: 0.5rem;
}
.source-ref button:hover {
  border-color: var(--ink);
  color: var(--ink);
}
.evidence-comparison {
  margin-top: 3rem;
  padding: 1.5rem;
  background: #f9f9f9;
  border-radius: 6px;
}
.table-wrapper {
  overflow-x: auto;
  margin: 1rem 0;
}
.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}
.data-table th, .data-table td {
  border: 1px solid var(--line);
  padding: 0.5rem;
  text-align: center;
}
.data-table th {
  background: #eee;
  font-weight: bold;
}
.data-table tr:hover {
  background: #f0f0f0;
}
.table-note {
  font-size: 0.85rem;
  color: var(--muted);
  font-style: italic;
}
.limitations-box {
  margin-top: 2rem;
  padding: 1rem;
  background: #fff8e1;
  border-left: 4px solid var(--warm);
  border-radius: 4px;
}
.limitations-box h3 {
  margin-top: 0;
  color: var(--warm);
}
.limitations-box ul {
  padding-left: 1.5rem;
  margin-bottom: 0;
}
.limitations-box li {
  margin-bottom: 0.5rem;
  font-size: 0.95rem;
}
@media (max-width: 600px) {
  .chapter-container { padding: 1rem 0.5rem; }
  .content-block { padding: 1rem; }
  .formula-box { font-size: 1rem; padding: 0.5rem; }
  .step-btn { font-size: 0.8rem; padding: 0.4rem 0.8rem; }
}
button[data-source]{background:#fff!important;color:#265976!important}
.katex{display:inline-block;max-width:100%;overflow-x:auto;vertical-align:middle}.step-controls,.control-buttons{flex-wrap:wrap} @media(max-width:480px){.metric-card,.stat-card{min-width:0}}

javascript:
(function() {
  'use strict';
  const stepper = document.getElementById('stepper-transform');
  if (!stepper) return;
  const buttons = stepper.querySelectorAll('.step-btn');
  const contents = stepper.querySelectorAll('.step-content');

  function showStep(index) {
    buttons.forEach((btn, i) => {
      btn.classList.toggle('active', i === index);
    });
    contents.forEach((content, i) => {
      content.classList.toggle('active', i === index);
    });
  }

  buttons.forEach((btn, i) => {
    btn.addEventListener('click', () => showStep(i));
  });
  showStep(0);

  const tableBody = document.querySelector('#table-mse-near tbody');
  if (tableBody && window.paperMindData && window.paperMindData.tables) {
    const tableData = window.paperMindData.tables.find(t => t.id === 'p8-Table_1');
    if (tableData && tableData.rows) {
      tableData.rows.forEach(row => {
        const tr = document.createElement('tr');
        const labelCell = document.createElement('td');
        labelCell.textContent = row.label;
        tr.appendChild(labelCell);
        const cols = ['M = 3', 'M = 4', 'M = 5', 'M = 6', 'M = 7', 'M = 8', 'M = 9', 'M = 10'];
        cols.forEach(col => {
          const td = document.createElement('td');
          const val = row.values[col];
          td.textContent = val !== null && val !== undefined ? val : '-';
          if (row.label === 'E') {
            td.style.fontWeight = 'bold';
            td.style.color = '#e67e22';
          }
          tr.appendChild(td);
        });
        tableBody.appendChild(tr);
      });
    }
  }

  const sourceButtons = document.querySelectorAll('button[data-source]');
  sourceButtons.forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      const sourceId = btn.getAttribute('data-source');
      if (window.paperMindData && window.paperMindData.sources && window.paperMindData.sources[sourceId]) {
        const source = window.paperMindData.sources[sourceId];
        const msg = `来源 ID: ${sourceId}\n页码：${source.page}\n原文：${source.quote}`;
        alert(msg);
      }
    });
  });
})();
